def maximum_target_frequency_after_subarray(nums,k):
    base=nums.count(k);best=0
    for value in set(nums):
        if value==k:continue
        gain=current=0
        for number in nums:
            current=max(0,current+(number==value)-(number==k));gain=max(gain,current)
        best=max(best,gain)
    return base+best

